#' Outlier multivariati
#'
#' 
#' @param data .
#' @param vars Le variabili quantitative su cui misurare la distanza di ogni
#'   osservazione dal centro dei dati, di solito quelle della base della
#'   segmentazione o della PCA.
#' @param alpha Un'osservazione è un outlier quando la probabilità di una
#'   distanza almeno così grande, secondo il chi-quadrato con tanti gradi di
#'   libertà quante sono le variabili, è minore della soglia.
#' @param tuto Se TRUE mostra il pannello con la descrizione dell'analisi.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$riepilogo} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$outlier} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$distOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$outlierOV} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$riepilogo$asDF}
#'
#' \code{as.data.frame(results$riepilogo)}
#'
#' @export
mvoutliers <- function(
    data,
    vars,
    alpha = 0.001,
    tuto = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("mvoutliers requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- mvoutliersOptions$new(
        vars = vars,
        alpha = alpha,
        tuto = tuto)

    analysis <- mvoutliersClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

